import{_ as e,o as a,c as i,a2 as o}from"./chunks/framework.DGk0zlJw.js";const b=JSON.parse('{"title":"B-705 L0 行为铁律检查（只看不弹，RFC §6.2.7）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/acceptance-B705-L0-behavior.md","filePath":"zh/acceptance-B705-L0-behavior.md"}'),d={name:"zh/acceptance-B705-L0-behavior.md"};function l(r,t,c,n,h,s){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="b-705-l0-行为铁律检查-只看不弹-rfc-§6-2-7" tabindex="-1">B-705 L0 行为铁律检查（只看不弹，RFC §6.2.7） <a class="header-anchor" href="#b-705-l0-行为铁律检查-只看不弹-rfc-§6-2-7" aria-label="Permalink to &quot;B-705 L0 行为铁律检查（只看不弹，RFC §6.2.7）&quot;">​</a></h1><blockquote><p>状态：代码侧静态审计完成（本文档记录）；逐条真机手动验证归入 B-803 全流程走查（首台 Windows 环境执行）。</p></blockquote><h2 id="铁律对照" tabindex="-1">铁律对照 <a class="header-anchor" href="#铁律对照" aria-label="Permalink to &quot;铁律对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>铁律</th><th>代码保证</th><th>结果</th></tr></thead><tbody><tr><td>1</td><td>L0 只展示状态、点击下钻（L2 或 L3）</td><td><code>PinnedHostWindow.TileActivated</code> 唯一点击出口 → <code>QuickPanelWindow.Toggle()</code>（L2）；无其他行为入口</td><td>✅ 审计通过</td></tr><tr><td>2</td><td>不产生任何弹窗/Toast/声音</td><td><code>PinnedHostWindow.cs</code> 全文无 Toast/ContentDialog/MessageBox/Sound/Play 调用；L0 对 Alert 的唯一表达是状态灯变色（<code>PinTile.Update</code>）</td><td>✅ 审计通过</td></tr><tr><td>3</td><td>不承载需要确认的 Action</td><td>L0 无 Action 入口（无 ActionRunner 引用）；仅可下钻</td><td>✅ 审计通过</td></tr><tr><td>4</td><td>永不抢焦点、不进 Alt-Tab/任务栏</td><td><code>WS_EX_NOACTIVATE + WS_EX_TOOLWINDOW</code>、<code>IsShownInSwitchers=false</code>、Topmost、拖动/悬停全用指针事件（不 Activate）</td><td>✅ 审计通过（真机复核归 B-803）</td></tr></tbody></table><h2 id="critical-表达-铁律-2-补充" tabindex="-1">Critical 表达（铁律 2 补充） <a class="header-anchor" href="#critical-表达-铁律-2-补充" aria-label="Permalink to &quot;Critical 表达（铁律 2 补充）&quot;">​</a></h2><ul><li>现状：Critical 仅状态灯变红（<code>SeverityPalette.Color(Critical)</code>），无任何打断。</li><li>脉冲动画（≤1Hz×intensity）属 <strong>B-707 动效系统</strong>范围（RFC §6.2.8：reduced 档默认脉冲）；B-707 落地后本表复核「灯脉冲仍不发声不弹窗」。</li></ul><h2 id="alert-通道分离" tabindex="-1">Alert 通道分离 <a class="header-anchor" href="#alert-通道分离" aria-label="Permalink to &quot;Alert 通道分离&quot;">​</a></h2><ul><li>Alert 一律走 NotificationEngine（B-502）→ Toast/声音由规则表驱动；L0 不订阅 NotificationRaised、不接触 INotificationSink（grep 证据见上）。</li></ul><h2 id="真机手动清单-归-b-803-执行时勾选" tabindex="-1">真机手动清单（归 B-803 执行时勾选） <a class="header-anchor" href="#真机手动清单-归-b-803-执行时勾选" aria-label="Permalink to &quot;真机手动清单（归 B-803 执行时勾选）&quot;">​</a></h2><ul><li>[ ] 注入 Critical 状态：L0 仅变色（B-707 后为脉冲），无弹窗/声音打断；Toast 照常由通知引擎发出</li><li>[ ] 断网：tile 变灰空心灯 + Last update（B-704），无任何异常弹窗；恢复后自动复位</li><li>[ ] 点击 tile → L2 打开并聚焦；失焦自动关闭；ESC 关闭</li><li>[ ] Alt-Tab 列表与任务栏均不见 L0 宿主；点击 tile 不打断当前输入焦点</li><li>[ ] 贴死屏边拖放 → 收起细条；悬停展开、水滴点击弹回展开、展开态点击进 L2；近边松手不误收（B-703+坍缩可逆修订）</li></ul>',10)])])}const _=e(d,[["render",l]]);export{b as __pageData,_ as default};
